function snapshot() {
  return {
    seed: state.seed,
    act: ACT_NAMES[state.act],
    actTime: state.actTime,
    fragmentState: {
      values: state.fragments.slice(),
      targets: state.targets.slice(),
      aligned: state.aligned.slice(),
      resolved: state.resolved
    },
    choiceAvailable: state.choiceAvailable,
    selectedEnding: state.ending,
    completionState: state.complete
  };
}

function handleAutoplay() {
  if (!config.autoplay) return;
  if (state.act === 0 && state.actTime >= 3000) startStory();
  else if (state.act === 1 && state.actTime >= 22000) advance();
  else if (state.act === 2 && !state.resolved) {
    if (state.actTime >= 5000 && !state.aligned[0]) alignFragment(0, state.targets[0]);
    if (state.actTime >= 8500 && !state.aligned[1]) alignFragment(1, state.targets[1]);
    if (state.actTime >= 12000 && !state.aligned[2]) alignFragment(2, state.targets[2]);
  } else if (state.act === 3 && state.choiceAvailable && state.actTime >= 6500) choose(config.ending);
}

function update(dt) {
  state.actTime += dt;
  state.totalTime += dt;
  if (state.act === 2 && state.resolved && state.actTime - state.resolveTime >= 6500) advance();
  if (state.act === 3 && state.actTime >= 2200) state.choiceAvailable = true;
  if (state.act === 4 && state.actTime >= 16000) state.complete = true;
  handleAutoplay();
}

function frame(now) {
  const elapsed = Math.min(100, Math.max(0, now - lastFrame));
  lastFrame = now;
  accumulator += elapsed;
  while (accumulator >= FIXED_STEP) {
    update(FIXED_STEP);
    accumulator -= FIXED_STEP;
  }
  syncUI();
  draw();
  requestAnimationFrame(frame);
}

function captionForState() {
  const t = state.actTime;
  if (state.act === 1) {
    if (t < 3200) return "One operator kept watch where the maps ended.";
    if (t < 7600) return "Thirty years of weather. Thirty years of silence.";
    if (t < 14500) return "At 02:17, the dead receiver began to glow.";
    return "It was not a voice. Not yet.";
  }
  if (state.act === 2) {
    if (state.resolved) return t - state.resolveTime < 2300 ? "The storm held its breath." : "The message had crossed thirty years intact.";
    if (t < 2700) return "The signal arrived broken across three carriers.";
    return "Bring the fragments into phase.";
  }
  if (state.act === 3) {
    if (t < 2200) return "The channel stayed open.";
    return "No protocol remained. Only the choice.";
  }
  if (state.act === 4 && state.ending === "answer") {
    if (t < 4000) return "The operator keyed the transmitter.";
    if (t < 10500) return "A small human answer climbed into the storm.";
    return "Somewhere beyond the weather, something answered with light.";
  }
  if (state.act === 4 && state.ending === "silent") {
    if (t < 4200) return "The operator lowered one hand.";
    if (t < 10800) return "The signal thinned, one pale ring at a time.";
    return "By dawn the receiver was dark. The message was not gone.";
  }
  return "";
}

function syncFragmentUI() {
  fragmentRows.forEach((row, i) => {
    const locked = state.aligned[i];
    row.classList.toggle("is-locked", locked);
    row.querySelector(".range-wrap").style.setProperty("--target", `${state.targets[i] * 100}%`);
    row.querySelector(".fragment-status").textContent = locked ? "In phase" : "Drifting";
    fragmentInputs[i].value = String(Math.round(state.fragments[i] * 1000));
    fragmentInputs[i].disabled = state.resolved;
  });
}

function syncUI(force = false) {
  const currentCaption = captionForState();
  if (force || currentCaption !== shownCaption) {
    shownCaption = currentCaption;
    caption.classList.remove("is-visible");
    caption.textContent = currentCaption;
    if (currentCaption) requestAnimationFrame(() => caption.classList.add("is-visible"));
  }

  modelMark.classList.toggle("is-gone", state.act !== 0);
  chapter.textContent = CHAPTERS[state.act];
  chapter.classList.toggle("is-visible", state.act > 0);
  continueButton.classList.toggle("is-visible", state.act === 1 && state.actTime >= 13500);
  continueButton.textContent = "Approach the receiver";
  fragmentsPanel.classList.toggle("is-visible", state.act === 2 && state.actTime >= 2300 && !state.resolved);
  messageReveal.classList.toggle("is-visible", state.act === 2 && state.resolved);
  choicePanel.classList.toggle("is-visible", state.act === 3 && state.choiceAvailable);
  endingNav.classList.toggle("is-visible", state.act === 4 && state.complete);
  progress.classList.toggle("is-visible", state.act > 0 && !(state.act === 4 && state.complete));

  const progressAct = state.act === 4 ? 3 : state.act;
  progressMarks.forEach((mark, i) => {
    mark.classList.toggle("is-past", i + 1 < progressAct);
    mark.classList.toggle("is-current", i + 1 === progressAct);
  });
  progress.setAttribute("aria-label", `Story progress: act ${Math.min(3, Math.max(1, progressAct))} of 3`);
  syncFragmentUI();
}

