      function runSelfTest() {
        const savedState = JSON.parse(JSON.stringify(state));
        const savedConfig = { ...config };
        const tests = [];
        const test = (name, passed, detail = "") => tests.push({ name, passed: Boolean(passed), detail });
        try {
          config.autoplay = false;
          reset(4417);
          const first = snapshot();
          reset(4417);
          const second = snapshot();
          test("deterministic reset", JSON.stringify(first) === JSON.stringify(second));

          const gatedValue = state.fragments[0];
          alignFragment(0, state.targets[0]);
          test("fragment gating", state.fragments[0] === gatedValue && !state.resolved, "alignment is rejected before act two");

          const order = [state.act];
          startStory();
          order.push(state.act);
          seek(16000);
          advance();
          order.push(state.act);
          state.targets.forEach((target, i) => alignFragment(i, target));
          runFor(9000);
          order.push(state.act);
          test("ordered act progression", JSON.stringify(order) === JSON.stringify([0, 1, 2, 3]), order.join(" → "));
          test("fragment gate opens choice", state.resolved && state.choiceAvailable);

          choose("answer");
          test("answer ending reachable", state.act === 4 && state.ending === "answer");

          reset(4417);
          startStory();
          seek(16000);
          advance();
          state.targets.forEach((target, i) => alignFragment(i, target));
          runFor(9000);
          choose("silent");
          test("silent ending reachable", state.act === 4 && state.ending === "silent");

          reset(4417);
          test("replay returns to beginning", state.act === 0 && !state.complete && state.ending === null);

          reset(90217);
          setAutoplay(true, "silent");
          runFor(90000);
          test("autoplay uses real path", state.act === 4 && state.ending === "silent" && state.complete);
          test("finite numeric state", allFinite(snapshot()));
        } catch (error) {
          tests.push({ name: "self-test execution", passed: false, detail: String(error && error.message ? error.message : error) });
        }

        state = savedState;
        config.autoplay = savedConfig.autoplay;
        config.ending = savedConfig.ending;
        weather = makeWeather(state.seed);
        shownCaption = "";
        syncUI(true);
        draw();
        return { passed: tests.every(item => item.passed), tests };
      }

      startButton.addEventListener("click", startStory);
      continueButton.addEventListener("click", advance);
      fragmentInputs.forEach((input, index) => {
        input.addEventListener("input", () => alignFragment(index, Number(input.value) / 1000));
      });
      choiceButtons.forEach(button => button.addEventListener("click", () => choose(button.dataset.ending)));
      replayButton.addEventListener("click", () => {
        config.autoplay = false;
        reset(state.seed);
        startButton.focus();
      });
      alternateButton.addEventListener("click", () => {
        const alternate = state.ending === "answer" ? "silent" : "answer";
        state.act = 3;
        state.actTime = 2300;
        state.choiceAvailable = true;
        state.complete = false;
        state.ending = null;
        syncUI(true);
        choose(alternate);
      });

      document.addEventListener("keydown", event => {
        if (event.key !== " " && event.key !== "Enter") return;
        const target = event.target;
        if (target instanceof HTMLButtonElement || target instanceof HTMLInputElement) return;
        if (state.act === 0 || (state.act === 1 && state.actTime >= 12000) || (state.act === 2 && state.resolved)) {
          event.preventDefault();
          advance();
        }
      });

      document.addEventListener("visibilitychange", () => {
        lastFrame = performance.now();
        accumulator = 0;
      });
      addEventListener("resize", resize, { passive: true });

      window.__LAST_SIGNAL__ = Object.freeze({
        reset,
        setAutoplay,
        seek,
        alignFragment,
        choose,
        snapshot,
        runSelfTest
      });

      reset(DEFAULT_SEED);
      resize();
      requestAnimationFrame(frame);
    })();
