function fragAligned(i){ return Math.abs(S.frag[i]-W.targets[i]) < TOL; }

function setFrag(i, v){
  i |= 0;
  if(i<0 || i>2 || S.act!=="act2" || S.locked) return false;
  v = Number(v);
  if(!Number.isFinite(v)) return false;
  S.frag[i] = clamp(v, 0, 1);
  return S.frag[i];
}

/* ---------- simulation (fixed step, no DOM) ---------- */
function stepSim(dt){
  S.t += dt; S.worldT += dt;
  if(S.act === "act1"){
    if(S.t >= A1) toAct("act2");
  }
  else if(S.act === "act2"){
    if(!S.locked){
      if(S.autoplay){
        for(let i=0;i<3;i++){
          const win = AUTO_WIN[i];
          if(S.t >= win[1]) { if(!fragAligned(i)) setFrag(i, W.targets[i]); }
          else if(S.t >= win[0]){
            const v = S.frag[i];
            setFrag(i, v + (W.targets[i]-v) * (1 - Math.exp(-dt/700)));
          }
        }
      }
      for(let i=0;i<3;i++){
        if(fragAligned(i)){ if(S.lockT[i] < 0) S.lockT[i] = S.worldT; }
        else S.lockT[i] = -1;
      }
      if(fragAligned(0) && fragAligned(1) && fragAligned(2)){
        S.locked = true; S.alignedAt = S.t;
      }
    } else if(S.t >= S.alignedAt + REVEAL){
      toAct("act3");
    }
  }
  else if(S.act === "act3"){
    if(S.autoplay && !S.choice && S.t >= A3_AUTO) doChoose(S.autoEnding);
  }
  else if(S.act === "ending"){
    if(S.t >= AE) toAct("end");
  }
}
function doChoose(e){
  if(S.act !== "act3" || S.choice || S.t < A3_SHOW) return false;
  if(e !== "answer" && e !== "silent") return false;
  S.choice = e;
  toAct("ending");
  return true;
}
function syncWorldT(){ S.worldT = S.actStartWorld + S.t; }

/* ---------- public deterministic interface ---------- */
function apiReset(seed){
  let n = Math.trunc(Number(seed));
  if(!Number.isFinite(n)) n = BOOT.seed;
  const ap = S ? S.autoplay : false;
  const ae = S ? S.autoEnding : "answer";
  W = deriveWorld(n);
  S = freshState(n);
  S.autoplay = ap; S.autoEnding = ae;
  buildGrain();
  ridgeCache.key = "";
  return apiSnapshot();
}
function apiSetAutoplay(enabled, ending){
  S.autoplay = !!enabled;
  if(ending === "answer" || ending === "silent") S.autoEnding = ending;
  return { enabled: S.autoplay, ending: S.autoEnding };
}
function apiSeek(ms){
  ms = Number(ms);
  if(!Number.isFinite(ms) || ms < 0) ms = 0;
  if(S.act === "act1") S.t = Math.min(ms, A1-1);
  else if(S.act === "act2"){
    S.t = S.locked ? clamp(ms, S.alignedAt, S.alignedAt + REVEAL - 1) : Math.min(ms, 6e6);
  }
  else if(S.act === "act3") S.t = Math.min(ms, 6e6);
  else if(S.act === "ending") S.t = Math.min(ms, AE-1);
  else S.t = Math.min(ms, 6e6);
  syncWorldT();
  return r3(S.t);
}
function apiAlign(index, value){ return setFrag(index, value); }
function apiChoose(e){ return doChoose(e); }
function apiSnapshot(){
  return {
    seed: S.seed,
    act: S.act,
    actTime: r3(S.t),
    worldTime: r3(S.worldT),
    fragments: {
      values: S.frag.map(r3),
      targets: W.targets.map(r3),
      aligned: [0,1,2].map(fragAligned),
      locked: S.locked,
      alignedAt: r3(S.alignedAt),
    },
    messageRevealed: S.act==="act3" || S.act==="ending" || S.act==="end" ||
                     (S.locked && S.t >= S.alignedAt + 1400),
    choiceAvailable: S.act === "act3" && S.t >= A3_SHOW && !S.choice,
    ending: S.choice,
    completed: S.completed,
    autoplay: { enabled: S.autoplay, ending: S.autoEnding },
  };
}
function apiSelfTest(){
  const saved = structuredClone(S);
  const tests = [];
  const T = (name, pass, detail)=> tests.push(detail ? {name, passed:!!pass, detail} : {name, passed:!!pass});
  const adv = ms => { let n = Math.round(ms/STEP); while(n-- > 0) stepSim(STEP); };
  const snapJ = ()=> JSON.stringify(apiSnapshot());
  try{
    // deterministic reset
    apiReset(917); apiSetAutoplay(false);
    adv(5000); const s1 = snapJ();
    apiReset(917); adv(5000); const s2 = snapJ();
    T("deterministic-reset", s1 === s2);
    // seek matches stepping
    apiReset(917); adv(6000); const s3 = snapJ();
    apiReset(917); apiSeek(6000); const s4 = snapJ();
    T("seek-deterministic", s3 === s4);
    // ordered act progression + answer ending via autoplay
    apiReset(917); apiSetAutoplay(true, "answer");
    let g = 0; while(!S.completed && g++ < 20000) stepSim(STEP);
    const hist = S.history.join(">");
    T("act-order", hist === "act1>act2>act3>ending>end", hist);
    T("autoplay-and-answer-ending", S.completed && S.choice === "answer");
    // automatic startup configuration
    T("startup-config", BOOT.seed===217 && BOOT.autoplay===true && BOOT.ending==="answer" && BOOT.applied===true);
    // fragment gating
    apiReset(917); apiSetAutoplay(false);
    adv(A1 + 200);
    const inAct2 = S.act === "act2";
    const rejectedEarly = apiChoose("answer") === false;
    adv(25000);
    const heldWithoutAlign = S.act === "act2" && !S.locked;
    W.targets.forEach((tg,i)=> apiAlign(i, tg));
    adv(400);
    const lockedNow = S.locked;
    adv(REVEAL + 400);
    T("fragment-gating", inAct2 && rejectedEarly && heldWithoutAlign && lockedNow && S.act === "act3");
    // choice gating + silent ending
    const earlyChoiceRejected = S.t < A3_SHOW ? apiChoose("silent") === false : true;
    adv(A3_SHOW + 300);
    const accepted = apiChoose("silent") === true;
    g = 0; while(!S.completed && g++ < 4000) stepSim(STEP);
    T("silent-ending", earlyChoiceRejected && accepted && S.completed && S.choice === "silent");
    // replay
    apiReset(917);
    T("replay", S.act === "act1" && S.t === 0 && !S.completed && S.choice === null);
    // autoplay can select the silent ending
    apiSetAutoplay(true, "silent");
    g = 0; while(!S.completed && g++ < 20000) stepSim(STEP);
    T("autoplay-silent-ending", S.completed && S.choice === "silent");
    // finite numeric state
    const nums = [];
    (function walk(v){
      if(typeof v === "number") nums.push(v);
      else if(Array.isArray(v)) v.forEach(walk);
      else if(v && typeof v === "object") Object.keys(v).forEach(k=>walk(v[k]));
    })(apiSnapshot());
    T("finite-numeric-state", nums.length > 8 && nums.every(Number.isFinite));
  }catch(err){
    T("no-exception", false, String(err));
  }
  // restore the state the visible story was in (incl. automatic-start defaults)
  W = deriveWorld(saved.seed);
  S = saved;
  buildGrain();
  ridgeCache.key = "";
  return { passed: tests.every(t=>t.passed), tests };
}

window.__LAST_SIGNAL__ = Object.freeze({
  reset: apiReset,
  setAutoplay: apiSetAutoplay,
  seek: apiSeek,
  alignFragment: apiAlign,
  choose: apiChoose,
  snapshot: apiSnapshot,
  runSelfTest: apiSelfTest,
});

/* ---------- canvas & layout ---------- */
const canvas = document.getElementById("scene");
const ctx = canvas.getContext("2d");
const RMQ = window.matchMedia ? window.matchMedia("(prefers-reduced-motion: reduce)") : { matches:false };
let vw = 1, vh = 1, U = 1;

function onResize(){
  vw = Math.max(1, window.innerWidth);
  vh = Math.max(1, window.innerHeight);
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(vw*dpr);
  canvas.height = Math.round(vh*dpr);
  ctx.setTransform(dpr,0,0,dpr,0,0);
  U = clamp(Math.min(vw,vh)/720, 0.45, 1.6);
  ridgeCache.key = "";
}
window.addEventListener("resize", onResize);

const ridgeCache = { key:"", pts:null, station:null };
function layout(){
  const key = vw+"x"+vh+"s"+S.seed;
  if(ridgeCache.key === key) return ridgeCache;
  const pts = [];
  for(let j=0;j<=72;j++){
    const x01 = j/72;
    pts.push([x01*vw, vh*(0.735 + (noise1(x01*2.6+7.31)-0.5)*0.11 - x01*0.018)]);
  }
  const sx01 = 0.68;
  const ry = vh*(0.735 + (noise1(sx01*2.6+7.31)-0.5)*0.11 - sx01*0.018);
  const sx = sx01*vw;
  const tx = sx + 36*U;
  const dish = { x: tx, y: ry - 100*U };
  const ax = Math.sin(-0.3), ay = -Math.cos(-0.3);
  const focal = { x: dish.x + ax*42*U, y: dish.y + ay*42*U };
  ridgeCache.key = key;
  ridgeCache.pts = pts;
  ridgeCache.station = { sx, ry, tx, dish, focal };
  return ridgeCache;
}

/* film grain tile, seeded */
let grainCv = null;
function buildGrain(){
  grainCv = document.createElement("canvas");
  grainCv.width = grainCv.height = 96;
  const g = grainCv.getContext("2d");
  const img = g.createImageData(96,96);
  const rng = mulberry32(W.grainSeed);
  for(let i=0;i<img.data.length;i+=4){
    const v = 118 + (rng()*80|0);
    img.data[i]=v; img.data[i+1]=v; img.data[i+2]=v; img.data[i+3]=255;
  }
  g.putImageData(img,0,0);
}

/* ---------- scene parameters per act ---------- */
function endingParams(kind, t, o){
  if(kind === "answer"){
    o.storm  = lerp(0.40, 0.10, ez(t, 3000, 12000));
    o.glow   = (0.9 + 0.5*fio(t,0,700,1200,2400)) * (1 - 0.7*ez(t, 18500, 21500));
    o.flick  = 0.12;
    o.beam   = ez(t, 1000, 5200);

    o.flick  = 0.12;
    o.beam   = ez(t, 1000, 5200);
    o.beamA  = 1 - ez(t, 18500, 21500);
    o.part   = ez(t, 3000, 10000);
    o.ringT  = t > 5200 ? (t-5200) : -1;
    o.ringA  = 1 - ez(t, 20500, 23200);
    o.starA  = ez(t, 8000, 15000);
    o.aurora = 0.35 + 0.4*ez(t, 5000, 12000);
    o.lift   = ez(t, 6800, 9600);
    o.veil   = Math.max(o.veil, (1 - rmp(t,0,600)) * 0.5);
    o.endFade= ez(t, 21500, 23800);
  } else {
    const A = Math.max(0, 1 - t/12000);
    const period = 3000 + t*0.28;
    const pulse = 0.5 + 0.5*Math.cos(Math.PI*2*t/period);
    o.storm  = 0.40 * (1 - ez(t, 4000, 16000));
    o.glow   = (0.9*(0.25 + 0.75*A*pulse)) * (1 - ez(t, 13000, 16500));
    o.flick  = 0.3;
    o.dawn   = ez(t, 10000, 22000) * 0.9;
    o.coldStar = ez(t, 13000, 19000);
    o.bow    = 0.12 + 0.5*ez(t, 6000, 9000);
    o.traceLife = 1 - ez(t, 3500, 10000);
    o.aurora = 0.35 * (1 - ez(t, 2000, 8000));
    o.darkVeil = Math.max(o.darkVeil, (1 - rmp(t,0,600)) * 0.45);
    o.endFade= ez(t, 21500, 23800);
  }
}
function sceneParams(){
  const t = S.t, act = S.act;
  const c = [closeness(0), closeness(1), closeness(2)];
  const cSum = c[0]+c[1]+c[2];
  const o = {
    t, act, c, cSum,
    storm:1, glow:0, flick:1, aurora:0, dawn:0,
    beam:0, beamA:1, part:0, ringT:-1, ringA:1, starA:0, coldStar:0,
    zoom:1, zx:0.5, zy:0.5, fg:1, bow:0.32, lift:0,
    traceLife:0, veil:0, darkVeil:0, endFade:0, endDim:0,
  };
  if(act === "act1"){
    o.glow = ez(t, 11800, 14500) * 0.85;
    o.flick = 1;
    o.traceLife = ez(t, 11800, 13400) * 0.85;
    o.fg = ez(t, 1400, 3600);
    o.bow = 0.32 - 0.18*ez(t, 11800, 13800);
    const st = layout().station;
    o.zx = st.focal.x/vw; o.zy = st.focal.y/vh;
    o.zoom = 1 + 0.05*sstep(t/A1);
    if(t > 22600){
      const p = rmp(t, 22600, A1);
      o.zoom += p*p*1.5;
      o.veil = Math.max(o.veil, sstep(p));
    }
  }
  else if(act === "act2"){
    o.storm = 0.9 * (1 - 0.14*cSum);
    o.glow = 0.75 + 0.2*c[1];
    o.veil = Math.max(o.veil, 1 - rmp(t, 0, 1300));
  }
  else if(act === "act3"){
    o.storm = 0.75 * (1 - 0.14*cSum);
    o.glow = 0.9; o.flick = 0.15;
    o.aurora = 0.35;
    o.traceLife = 1;
    o.bow = 0.12;
    o.fg = ez(t, 300, 1400);
    o.zoom = 1 + 0.3*(1 - sstep(rmp(t, 0, 1700)));
    o.zx = 0.5; o.zy = 0.45;
    o.darkVeil = Math.max(o.darkVeil, (1 - rmp(t,0,700)) * 0.6);
  }
  else if(act === "ending"){
    o.storm = 0.40; o.glow = 0.9; o.traceLife = 1; o.bow = 0.12;
    endingParams(S.choice, t, o);
  }
  else { // end card
    o.storm = 0.40; o.glow = 0.9; o.traceLife = 1; o.bow = 0.12;
    endingParams(S.choice || "answer", AE, o);
    o.endFade = 0;
    o.endDim = 1 - 0.22*rmp(t, 0, 2000);
  }
  return o;
}

/* ---------- drawing helpers ---------- */
function drawSky(o){
  const NT=[5,8,15], NM=[10,15,28], NL=[17,24,42];
  const DT=[26,34,50], DM=[56,66,90], DL=[124,116,116];
  const AT=[3,5,12];
  let top = mixC(NT, DT, o.dawn), mid = mixC(NM, DM, o.dawn), low = mixC(NL, DL, o.dawn);
