const { spawn } = require("child_process");
const http = require("http");
const fs = require("fs");
const path = require("path");
const chromePath = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const file = path.resolve("index.html");
const url = "file://" + file;
const port = 9334;

function get(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = "";
      res.on("data", (c) => d += c);
      res.on("end", () => resolve(d));
    }).on("error", reject);
  });
}

function wsConnect(wsUrl) {
  return new Promise((resolve, reject) => {
    const WebSocket = require("ws");
    const ws = new WebSocket(wsUrl);
    ws.on("open", () => resolve(ws));
    ws.on("error", reject);
  });
}

async function main() {
  let wsMod = null;
  try { wsMod = require("ws"); } catch (e) {}
  if (!wsMod) {
    // minimal CDP over fetch + HTTP for /json then use undici websocket if available
  }
  const child = spawn(chromePath, [
    "--headless=new",
    "--disable-gpu",
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-background-networking",
    `--remote-debugging-port=${port}`,
    url
  ], { stdio: "ignore" });

  let json = null;
  for (let i = 0; i < 40; i++) {
    await new Promise(r => setTimeout(r, 150));
    try {
      json = JSON.parse(await get(`http://127.0.0.1:${port}/json/list`));
      if (json && json.length) break;
    } catch (e) {}
  }
  if (!json || !json.length) {
    console.error("NO_TARGETS", json);
    child.kill();
    process.exit(1);
  }
  const page = json.find(t => t.type === "page") || json[0];
  console.log("TARGET", page.title, page.url, page.webSocketDebuggerUrl ? "ws" : "no-ws");

  // Use Chrome's HTTP /json/runtime/evaluate isn't a thing. Need websocket.
  // Fallback: use fetch to /json/protocol? 
  // Implement a tiny WebSocket client if 'ws' missing.
  const wsUrl = page.webSocketDebuggerUrl;
  const WebSocket = global.WebSocket || (await import("node:http").then(() => null));

  // Node 22 has global WebSocket
  if (typeof globalThis.WebSocket !== "function") {
    console.error("NO_WEBSOCKET");
    child.kill();
    process.exit(1);
  }
  const ws = new globalThis.WebSocket(wsUrl);
  await new Promise((res, rej) => { ws.addEventListener("open", res); ws.addEventListener("error", rej); });
  let id = 0;
  const pending = new Map();
  ws.addEventListener("message", (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) pending.get(msg.id)(msg);
  });
  function send(method, params) {
    const i = ++id;
    return new Promise((resolve) => {
      pending.set(i, resolve);
      ws.send(JSON.stringify({ id: i, method, params }));
    });
  }
  await send("Runtime.enable");
  await send("Page.enable");
  // wait for load
  await new Promise(r => setTimeout(r, 800));
  const title = await send("Runtime.evaluate", { expression: "document.title", returnByValue: true });
  const h1 = await send("Runtime.evaluate", { expression: "document.querySelector('h1') && document.querySelector('h1').textContent", returnByValue: true });
  const api = await send("Runtime.evaluate", { expression: "typeof window.__LAST_SIGNAL__", returnByValue: true });
  const snap = await send("Runtime.evaluate", { expression: "JSON.stringify(window.__LAST_SIGNAL__.snapshot())", returnByValue: true });
  const test = await send("Runtime.evaluate", { expression: "JSON.stringify(window.__LAST_SIGNAL__.runSelfTest())", returnByValue: true, awaitPromise: true });
  const snap2 = await send("Runtime.evaluate", { expression: "JSON.stringify(window.__LAST_SIGNAL__.snapshot())", returnByValue: true });
  console.log("TITLE", title.result && title.result.value);
  console.log("H1", h1.result && h1.result.value);
  console.log("API", api.result && api.result.value);
  console.log("SNAP", snap.result && snap.result.value);
  console.log("TEST", test.result && test.result.value);
  console.log("SNAP2", snap2.result && snap2.result.value);
  const cons = await send("Runtime.evaluate", { expression: "window.__consoleErrors ? JSON.stringify(window.__consoleErrors) : '[]'", returnByValue: true });
  console.log("CONS", cons.result && cons.result.value);
  ws.close();
  child.kill();
}
main().catch(err => { console.error(err); process.exit(1); });
