node <<'NODE'
const { spawn } = require("child_process");
const http = require("http");
const fs = require("fs");
const path = require("path");
const chromePath = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const file = path.resolve("index.html");
const url = "file://" + file;
const port = 9338;

function get(u) {
  return new Promise((resolve, reject) => {
    http.get(u, (res) => {
      let d = "";
      res.on("data", (c) => d += c);
      res.on("end", () => resolve(d));
    }).on("error", reject);
  });
}

(async () => {
  const child = spawn(chromePath, [
    "--headless=new",
    "--disable-gpu",
    "--no-first-run",
    "--window-size=1280,720",
    "--force-device-scale-factor=1",
    "--allow-file-access-from-files",
    `--remote-debugging-port=${port}`,
    url
  ], { stdio: "ignore" });

  let json = null;
  for (let i = 0; i < 50; i++) {
    await new Promise(r => setTimeout(r, 120));
    try {
      json = JSON.parse(await get(`http://127.0.0.1:${port}/json/list`));
      if (json && json.some(t => t.type === "page" && t.url.includes("index.html"))) break;
    } catch (e) {}
  }
  const page = json.find(t => t.type === "page" && t.url.includes("index.html"));
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.addEventListener("open", res); ws.addEventListener("error", rej); });
  let id = 0;
  const pending = new Map();
  const logs = [];
  ws.addEventListener("message", (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.method === "Runtime.consoleAPICalled") logs.push(msg.params.type + ": " + (msg.params.args||[]).map(a=>a.value||a.description).join(" "));
    if (msg.method === "Runtime.exceptionThrown") logs.push("EXC: " + (msg.params.exceptionDetails && msg.params.exceptionDetails.text));
    if (msg.id && pending.has(msg.id)) pending.get(msg.id)(msg);
  });
  function send(method, params) {
    const i = ++id;
    return new Promise((resolve) => { pending.set(i, resolve); ws.send(JSON.stringify({ id: i, method, params })); });
  }
  await send("Runtime.enable");
  await send("Page.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
  await new Promise(r => setTimeout(r, 500));

  const test = await send("Runtime.evaluate", { expression: "JSON.stringify(window.__LAST_SIGNAL__.runSelfTest())", returnByValue: true });
  console.log("TEST", test.result.result.value);

  async function shot(name) {
    const pic = await send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(".", name), Buffer.from(pic.result.data, "base64"));
    const snap = await send("Runtime.evaluate", { expression: "JSON.stringify(window.__LAST_SIGNAL__.snapshot())", returnByValue: true });
    console.log("SHOT", name, snap.result.result.value);
  }

  await send("Runtime.evaluate", { expression: "window.__LAST_SIGNAL__.reset(217); window.__LAST_SIGNAL__.setAutoplay(true,'answer'); true", returnByValue: true });
  await new Promise(r => setTimeout(r, 600));
  await shot("_shot-open.png");

  // wait into glow (~14s) — rAF in headless should run
  await new Promise(r => setTimeout(r, 14500));
  await shot("_shot-glow.png");

  await new Promise(r => setTimeout(r, 12000));
  await shot("_shot-act2.png");

  console.log("LOGS", logs.join("\n") || "(none)");
  ws.close();
  child.kill();
})().catch(e => { console.error(e); process.exit(1); });
NODE

